const feeds = [
  // 1. Kategori Umum: Virtual Office & Coworking Nasional
  'https://news.google.com/rss/search?q=virtual+office+OR+coworking+space+indonesia+when:7d&hl=id&gl=ID&ceid=ID:id',

  // 2. Kategori Umum: UMKM & Startup Indonesia
  'https://news.google.com/rss/search?q=UMKM+OR+startup+indonesia+bisnis+when:7d&hl=id&gl=ID&ceid=ID:id',

  // 3. Kategori Umum: Sewa Kantor & Ruang Kerja Fleksibel
  'https://news.google.com/rss/search?q=sewa+kantor+OR+ruang+kerja+fleksibel+indonesia+when:7d&hl=id&gl=ID&ceid=ID:id',

  // 4. KHUSUS JAKARTA: Dinamika Kantor, Startup & Bisnis Jakarta
  'https://news.google.com/rss/search?q=kantor+OR+startup+OR+bisnis+jakarta+when:7d&hl=id&gl=ID&ceid=ID:id',

  // 5. KHUSUS JAKARTA: MRT, Transportasi & Kawasan Perkantoran Jakarta
  'https://news.google.com/rss/search?q=MRT+jakarta+OR+sewa+kantor+jakarta+when:7d&hl=id&gl=ID&ceid=ID:id',

  // 6. KHUSUS JAKARTA TIMUR: Industri, Logistik & Usaha Jakarta Timur
  'https://news.google.com/rss/search?q=industri+OR+logistik+OR+ekspedisi+jakarta+timur+when:7d&hl=id&gl=ID&ceid=ID:id',

  // 7. Portal Berita Ekonomi & Finansial Nasional
  'https://finance.detik.com/rss',
  'https://www.antaranews.com/rss/ekonomi',
  'https://www.cnbcindonesia.com/rss',
];

return feeds.map(u => ({
  json: {
    feedUrl: u
  }
}));

const cfg = $('Config').first().json;
const tax = $('GET Taxonomy').first().json;
const branches = ($('GET Branches').first().json.branches) || [];
const items = $input.all().map(i => i.json);

// =====================================================
// RETRY DATA
// =====================================================

let trigger = {};

try {
  trigger = $('When Executed by Another Workflow').first().json || {};
} catch (e) {
  trigger = {};
}

const excludeUrls = new Set(
  Array.isArray(trigger.excludeUrls)
    ? trigger.excludeUrls
    : []
);

const attemptCount = Number(trigger.attemptCount || 0);

// =====================================================
// CONFIG
// =====================================================

// Maksimal usia berita yang masih boleh dipakai
const MAX_AGE_DAYS = 180;

// Maksimal kandidat yang akan dicek ke check.php
const MAX_DUPLICATE_CHECKS = 50;

// =====================================================
// KEYWORDS (Termasuk Kata Kunci Koridor Jakarta)
// =====================================================

const KW = [
  'virtual office',
  'coworking',
  'private office',
  'sewa kantor',
  'ruang kerja',
  'kantor virtual',
  'umkm',
  'startup',
  'wirausaha',
  'ekspansi bisnis',
  'legalitas',
  'pt perorangan',
  'pma',
  'wfa',
  'work from anywhere',
  'ruang meeting',
  'event space',
  'produktivitas',
  'pajak',
  'npwp',
  'izin usaha',
  'bisnis',
  'ekonomi',
  'investasi',
  // Tambahan Koridor Jakarta & Bisnis
  'jakarta',
  'mrt',
  'fatmawati',
  'simatupang',
  'cilandak',
  'jatinegara',
  'cakung',
  'scbd',
  'sudirman',
  'logistik'
];

// =====================================================
// PARSE DATE
// =====================================================

function getItemDate(it) {
  const raw = it.isoDate || it.pubDate || '';

  if (!raw) {
    return null;
  }

  const d = new Date(raw);

  if (Number.isNaN(d.getTime())) {
    return null;
  }

  return d;
}

// =====================================================
// HITUNG UMUR BERITA
// =====================================================

function getAgeDays(it, now) {
  const d = getItemDate(it);

  if (!d) {
    return null;
  }

  const diffMs = now.getTime() - d.getTime();
  const diffDays = diffMs / (1000 * 60 * 60 * 24);

  return diffDays;
}

// =====================================================
// FRESHNESS SCORE
// =====================================================

function freshnessScore(ageDays) {
  if (ageDays === null) {
    return 0;
  }

  if (ageDays < 1) {
    return 5;
  }

  if (ageDays <= 3) {
    return 4;
  }

  if (ageDays <= 7) {
    return 3;
  }

  if (ageDays <= 30) {
    return 2;
  }

  if (ageDays <= 180) {
    return 1;
  }

  return 0;
}

// =====================================================
// RELEVANCE SCORE
// =====================================================

function relevanceScore(it) {
  const text = (
    (it.title || '') +
    ' ' +
    (it.contentSnippet || it.content || '')
  ).toLowerCase();

  let score = 0;

  for (const k of KW) {
    if (text.includes(k)) {
      score += (k.length > 10 ? 2 : 1);
    }
  }

  return score;
}

// =====================================================
// WAKTU SEKARANG
// =====================================================

const now = new Date();

// =====================================================
// STEP 1 — FILTER FRESHNESS
// =====================================================

const freshnessRejected = [];
const freshItems = [];

for (const it of items) {
  const ageDays = getAgeDays(it, now);

  if (ageDays !== null && ageDays > MAX_AGE_DAYS) {
    freshnessRejected.push({
      title: it.title || '',
      link: it.link || '',
      pubDate: it.pubDate || '',
      isoDate: it.isoDate || '',
      ageDays: Number(ageDays.toFixed(2)),
      reason: 'older_than_180_days'
    });
    continue;
  }

  freshItems.push(it);
}

// =====================================================
// STEP 2 — SCORING RELEVANCE + FRESHNESS
// =====================================================

let scored = freshItems
  .map(it => {
    const ageDays = getAgeDays(it, now);
    const relevance = relevanceScore(it);
    const freshness = freshnessScore(ageDays);

    return {
      it,
      relevanceScore: relevance,
      freshnessScore: freshness,
      totalScore: relevance + freshness,
      ageDays
    };
  })
  .filter(x => x.relevanceScore > 0);

// =====================================================
// STEP 3 — SORT TOTAL SCORE
// =====================================================

scored.sort((a, b) => {
  if (b.totalScore !== a.totalScore) {
    return b.totalScore - a.totalScore;
  }

  if (b.relevanceScore !== a.relevanceScore) {
    return b.relevanceScore - a.relevanceScore;
  }

  if (a.ageDays === null && b.ageDays !== null) {
    return 1;
  }

  if (a.ageDays !== null && b.ageDays === null) {
    return -1;
  }

  if (a.ageDays !== null && b.ageDays !== null) {
    return a.ageDays - b.ageDays;
  }

  return 0;
});

// =====================================================
// STEP 4 — REMOVE DUPLICATE TITLE DI RSS
// =====================================================

const seenTitles = new Set();

scored = scored.filter(x => {
  const title = (x.it.title || '')
    .toLowerCase()
    .trim();

  if (!title) {
    return false;
  }

  if (seenTitles.has(title)) {
    return false;
  }

  seenTitles.add(title);
  return true;
});

// =====================================================
// STEP 5 — REMOVE URL DARI RETRY
// =====================================================

scored = scored.filter(
  x => !excludeUrls.has(x.it.link || '')
);

// =====================================================
// DEBUG LIST KANDIDAT
// =====================================================

const candidatePreview = scored
  .slice(0, MAX_DUPLICATE_CHECKS)
  .map(x => ({
    title: x.it.title || '',
    link: x.it.link || '',
    pubDate: x.it.pubDate || '',
    isoDate: x.it.isoDate || '',
    ageDays: x.ageDays !== null
      ? Number(x.ageDays.toFixed(2))
      : null,
    relevanceScore: x.relevanceScore,
    freshnessScore: x.freshnessScore,
    totalScore: x.totalScore
  }));

// =====================================================
// STEP 6 — DUPLICATE CHECK KE WEBSITE DATABASE
// =====================================================

let chosen = null;
const debugChecks = [];

const candidatesToCheck = scored.slice(
  0,
  MAX_DUPLICATE_CHECKS
);

for (const x of candidatesToCheck) {
  const link = x.it.link || '';
  const title = x.it.title || '';

  try {
    const res = await this.helpers.httpRequest({
      method: 'GET',
      url: cfg.siteBaseUrl + '/_api/check.php',
      qs: {
        source_url: link,
        title: title
      },
      headers: {
        'X-Automation-Token': cfg.automationToken
      },
      json: true,
    });

    debugChecks.push({
      title,
      link,
      duplicate: !!res?.duplicate,
      matched_by: res?.matched_by || null,
      post_id: res?.post?.id || null,
      post_status: res?.post?.status || null,
      post_title: res?.post?.title || null
    });

    if (res && res.duplicate) {
      continue;
    }

    chosen = x;
    break;

  } catch (e) {
    debugChecks.push({
      title,
      link,
      duplicate: false,
      check_error: e.message
    });

    chosen = x;
    break;
  }
}

// =====================================================
// STEP 7 — TIDAK ADA KANDIDAT
// =====================================================

if (!chosen) {
  return [
    {
      json: {
        hasTopic: false,
        attemptCount,
        excludeUrls: Array.from(excludeUrls),
        debug: {
          rssCount: items.length,
          freshCount: freshItems.length,
          freshnessRejectedCount: freshnessRejected.length,
          scoredCount: scored.length,
          checkedCount: debugChecks.length,
          maxDuplicateChecks: MAX_DUPLICATE_CHECKS,
          freshnessRejected: freshnessRejected.slice(0, 50),
          candidatePreview,
          checks: debugChecks
        }
      }
    }
  ];
}

// =====================================================
// STEP 8 — PENENTUAN TARGET CABANG BERDASARKAN JAM WIB
// =====================================================

// Ambil waktu lokal WIB (Asia/Jakarta)
const wibDate = new Date(now.toLocaleString('en-US', { timeZone: 'Asia/Jakarta' }));
const hourWib = wibDate.getHours();
const dayWib = wibDate.getDay(); // 0 = Minggu, 1 = Senin, 2 = Selasa, dst.

// Slot Jakarta: Jam 11 (10-12) dan Jam 19 (18-20)
const isSlot11 = hourWib >= 10 && hourWib < 13;
const isSlot19 = hourWib >= 18 && hourWib < 21;
const isJakartaSlot = isSlot11 || isSlot19;

let target_type = 'general';
let branch = null;

// Cari data cabang Fatmawati dan Gorebiz (Jakarta Timur)
const fatmawati = branches.find(b => b.slug === 'jakarta');
const gorebiz   = branches.find(b => b.slug === 'jakarta-timur');

if (isJakartaSlot) {
  target_type = 'branch';

  if (isSlot11) {
    // Slot 11:00 -> Wajib Fatmawati (Jakarta Selatan)
    branch = fatmawati || branches[0];
  } else {
    // Slot 19:00 -> Rotasi: Selasa & Jumat = Gorebiz (Jaktim), hari lain = Fatmawati
    if (dayWib === 2 || dayWib === 5) {
      branch = gorebiz || fatmawati || branches[0];
    } else {
      branch = fatmawati || branches[0];
    }
  }
} else {
  // Slot 08:00 & 15:00 -> Jalankan Flow Lama (70% General, 30% Cabang Acak)
  const isBranch = Math.random() < 0.30;

  if (isBranch && branches.length) {
    const doy = Math.floor(Date.now() / 86400000);
    const priority = [
      'surabaya',
      'jakarta',
      'malang',
      'surabaya-timur',
      'surabaya-barat',
      'jakarta-timur',
      'gresik',
      'medan'
    ];

    const ordered = priority
      .map(k => branches.find(b => b.slug === k))
      .filter(Boolean);

    const pool = ordered.length ? ordered : branches;
    branch = pool[doy % pool.length];
    target_type = 'branch';
  }
}

// =====================================================
// STEP 9 — OUTPUT KE NODE BERIKUTNYA
// =====================================================

return [
  {
    json: {
      hasTopic: true,
      topic_title: chosen.it.title || '',
      topic_summary: (
        chosen.it.contentSnippet ||
        chosen.it.content ||
        ''
      )
        .toString()
        .replace(/<[^>]+>/g, '')
        .slice(0, 500),
      source_url: chosen.it.link || '',
      target_type,
      branch,
      is_jakarta_slot: isJakartaSlot, // Flag penanda khusus slot Jakarta
      attemptCount,
      excludeUrls: Array.from(excludeUrls)
    }
  }
];

const cfg = $('Config').first().json;
const tax = $('GET Taxonomy').first().json;
const topic = $json;
const cats = (tax.categories || []).map(c => c.name).join(', ');
const tags = (tax.tags || []).map(t => t.name).join(', ');
let links = (tax.link_targets || []).map(l => ({ title: l.title, url: l.url }));

let branchJson = '';
if (topic.target_type === 'branch' && topic.branch) {
  branchJson = JSON.stringify(topic.branch, null, 2);
  if (topic.branch.detail_url) {
    links.unshift({ 
      title: topic.branch.name + ' (halaman cabang resmi)', 
      url: topic.branch.detail_url 
    });
  }
}

// =====================================================
// MASTER KEYWORDS URBAN OFFICE DARI 165 LIST
// =====================================================

// 1. Kumpulan Master Keyword Khusus Slot Jakarta (Jam 11 & 19)
const masterKeywordsJakarta = [
  'virtual office scbd',
  'virtual office tb simatupang',
  'virtual office sudirman',
  'virtual office pondok indah',
  'virtual office kemang',
  'virtual office kebayoran baru',
  'virtual office kota kasablanka',
  'virtual office Jakarta Selatan',
  'virtual office Fatmawati',
  'virtual office Jakarta Timur',
  'sewa virtual office Jakarta',
  'jasa virtual office Jakarta',
  'harga virtual office jakarta selatan',
  'virtual office untuk PT',
  'virtual office bisa pkp',
  'kbli virtual office',
  'pembuatan PT Jakarta'
];

// 2. Kumpulan Master Keyword Khusus Slot Umum & Surabaya (Jam 08 & 15)
const masterKeywordsUmum = [
  'virtual office Surabaya',
  'sewa virtual office Surabaya',
  'harga virtual office Surabaya',
  'kantor virtual Surabaya',
  'virtual office Surabaya Timur',
  'virtual office MERR',
  'virtual office Klampis',
  'virtual office untuk PT',
  'jasa pembuatan PT dan virtual office',
  'alamat bisnis untuk PT',
  'sewa kantor Surabaya',
  'meeting room Surabaya',
  'coworking space Surabaya',
  'serviced office Surabaya',
  'biaya virtual office',
  'cara kerja virtual office',
  'keuntungan kantor virtual',
  'apakah virtual office legal',
  'aturan virtual office'
];

// Pilih keyword berdasarkan slot jam yang aktif
const selectedKeywords = topic.is_jakarta_slot
  ? masterKeywordsJakarta.join(', ')
  : masterKeywordsUmum.join(', ');

// =====================================================
// SUSUN PROMPT UNTUK LLM
// =====================================================

const user = [
  'TOPIK SUMBER (pemicu sudut pandang — JANGAN disalin/rangkum):',
  '- judul: ' + (topic.topic_title || ''),
  '- ringkasan: ' + (topic.topic_summary || ''),
  '- source_url: ' + (topic.source_url || ''),
  '',
  'JENIS ARTIKEL: ' + topic.target_type,
  '',
  'DATA CABANG (fakta ASLI — pakai untuk GEO/E-E-A-T; kosong jika general):',
  branchJson,
  '',
  'TARGET MASTER KEYWORDS:',
  selectedKeywords,
  '(ATURAN KEYWORD: Wajib pilih 1 kata kunci dari daftar di atas sebagai kata kunci utama di Title, H2, dan Meta Title. Pilih 1-2 kata kunci lain sebagai pendukung di paragraf artikel. HINDARI keyword stuffing!).',
  '',
  'KATEGORI TERSEDIA (pilih 1-2 dari sini saja):',
  cats,
  '',
  'TAG TERSEDIA (pilih 6-10 paling relevan, HANYA dari sini):',
  tags,
  '',
  'LINK INTERNAL TERSEDIA (pakai URL persis, prioritaskan link cabang jika artikel branch):',
  JSON.stringify(links),
  '',
  'Tulis artikel sesuai seluruh aturan di system prompt. Keluarkan HANYA JSON.'
].join('\n');

return [{ 
  json: { 
    system: cfg.systemPrompt, 
    user, 
    source_url: topic.source_url, 
    target_type: topic.target_type, 
    topic_title: topic.topic_title 
  } 
}];

const raw = ($json.choices && $json.choices[0] && $json.choices[0].message && $json.choices[0].message.content) || '{}';
let txt = String(raw).trim();
if (txt.startsWith('```')) { txt = txt.replace(/^```(json)?/i, '').replace(/```$/,'').trim(); }
let d;
try { d = JSON.parse(txt); }
catch (e) { d = { reject: true, reject_reason: 'Output LLM bukan JSON valid: ' + e.message }; }
d.source_url = $('Build Prompt').item.json.source_url || '';
if (typeof d.categories === 'string') d.categories = [d.categories];
if (typeof d.tags === 'string') d.tags = [d.tags];
if (!Array.isArray(d.categories)) d.categories = [];
if (!Array.isArray(d.tags)) d.tags = [];
d.reject = d.reject === true;
return [{ json: d }];

