const pick = $('Pick Topic').first().json;
const parse = $('Parse LLM').first().json;

// Ambil excludeUrls sebelumnya, pastikan selalu Array
const previousExclude = Array.isArray(pick.excludeUrls)
  ? pick.excludeUrls
  : [];

// Ambil source URL artikel yang baru saja terdeteksi duplikat
const currentSourceUrl = String(parse.source_url || '').trim();

// Gabungkan URL lama + URL sekarang
const excludeUrls = [
  ...previousExclude,
  ...(currentSourceUrl ? [currentSourceUrl] : [])
];

// Naikkan attempt count
const attemptCount = Number(pick.attemptCount || 0) + 1;

return [
  {
    json: {
      excludeUrls,
      attemptCount
    }
  }
];
